head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gPageSize = 10; // 페이지 size
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
// 화면 리사이징
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    fn_Search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    const url_list = "/UnfaithfulDesign.do?method=listUnfaithfulLimitIsur&inputMessageId=NFAITHLIMITISUR_IN" + "&outputMessageId=NFAITHLIMITISUR_OUT";
    const url_cond = "&ISUR_NM_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&DEP_CD=" + scwin.gDepCd + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.gPageSize + "&SCREN_ID=" + 'ULDSTF35114.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let gCnt = 0;
    for (let k = 1; k <= dts_nfaith_list.getRowCount(); k++) {
        gStat = dts_nfaith_list.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            gCnt++;
        }
    }
    grd_Grid.Redraw = true;
    if (gCnt === 0) {
        await $c.win.alert("저장할 내용이 없습니다.");
        return;
    }
    if (window.confirm("[총" + gCnt + "건] 저장하겠습니까?")) {
        const url = "/UnfaithfulDesign.do?method=saveUnfaithfulLimitIsur&SCREN_ID=" + 'ULDSTF35114.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_nfaith_list)";
        trs_save.Post();
        dts_nfaith_list.reset();
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DESIGN_DD") {
        await $c.stf.openDisclViewer(scwin.gAcptNo, 'R');
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF35114.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "불성실공시법인지정 목록", type: "8"});
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadError
 * @description dts_nfaith_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadError = async function() {
    await $c.win.alert(dts_nfaith_list);
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadCompleted
 * @description dts_nfaith_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadCompleted = async function(rowcount) {
    if (dts_nfaith_list.errorMsg) {
        await $c.win.alert(dts_nfaith_list.errorMsg);
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        // alert(txb_TotalCnt.value );

    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else return true;
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name img_Isu_Srh_onclick
 * @description img_Isu_Srh 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Isu_Srh_onclick = function() {

};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    scwin.setCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
    if (js_dep_cd !== "3500" && js_dep_cd !== "3410" && js_dep_cd !== "3510" && js_dep_cd !== "ZSYS") {
        btn_Save.hide();
        btn_New.hide();
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.save();
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    // contnId = "input";
    const options = {
        id: "ULDSTF35115",
        title: "추가 등록",
        type: "browserPopup",
        width: "1100px",
        height: 575 + 100,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/dsclmgt/ULDSTF35115.gfm", options);
    // contnId = "";
    // fn_list_sync();

};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name trs_save_OnSuccess
 * @description save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_save_OnSuccess = async function() {
    await $c.win.alert("성공적으로 저장 되었습니다.");
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
